const STORAGE_WRITER_LOCK_SUFFIX: &str = ".scriptbots-writer.lock";
/// Sequence namespace reserved for core-owned pairwise interaction ordinals.
///
/// Legacy replay events use their position within the enclosing persistence batch. Interaction
/// events retain a per-source-tick ordinal instead, so placing them in this disjoint namespace
/// prevents a collision while preserving a stable identity across persistence windows.
pub const INTERACTION_REPLAY_SEQ_BASE: u64 = 1 << 62;
/// Sequence reserved for the one mandatory narrative input at each source tick.
///
/// Optional replay events occupy the low enumeration namespace and pairwise interactions begin
/// at [`INTERACTION_REPLAY_SEQ_BASE`]. A constant is sufficient because `tick` is also part of
/// the replay-events primary key.
pub const NARRATIVE_INPUT_REPLAY_SEQ: u64 = 1 << 61;
const NARRATIVE_INPUT_EVENT_TYPE: &str = "narrative_input_v1";
const NARRATIVE_INPUT_SCOPE: &str = "world:narrative";

#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum HostJournalFaultPoint {
    AfterWorkerReceive,
    AdmissionAfterTransactionBegin,
    AdmissionAfterArchiveInsert,
    AdmissionBeforeProgress,
    AdmissionBeforeCommit,
    AfterArchiveBeforeApplication,
    PersistenceAfterTransactionBegin,
    PersistenceAfterTicks,
    PersistenceAfterMetrics,
    PersistenceAfterEvents,
    PersistenceAfterAgents,
    PersistenceAfterBirths,
    PersistenceAfterDeaths,
    PersistenceAfterReplayEvents,
    PersistenceBeforeCommit,
    PersistenceRollbackAcknowledgementLost,
    BeforePersistenceFlush,
    BeforeDurableMarker,
    BeforePublication,
    BeforeAnalyticsPublication,
    AfterPublicationBeforeReceipt,
    BeforeShutdownCheckpointClose,
    BeforeRecoveryArchiveScan,
}

#[cfg(test)]
fn host_journal_faults() -> &'static Mutex<BTreeSet<(String, HostJournalFaultPoint)>> {
    static FAULTS: OnceLock<Mutex<BTreeSet<(String, HostJournalFaultPoint)>>> = OnceLock::new();
    FAULTS.get_or_init(|| Mutex::new(BTreeSet::new()))
}

#[cfg(test)]
fn arm_host_journal_fault(path: &str, point: HostJournalFaultPoint) {
    let inserted = host_journal_faults()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert((path.to_owned(), point));
    assert!(
        inserted,
        "host-journal fault {point:?} already armed for {path}"
    );
}

#[cfg(test)]
fn take_host_journal_fault(path: &str, point: HostJournalFaultPoint) -> bool {
    host_journal_faults()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .remove(&(path.to_owned(), point))
}

#[cfg(test)]
fn fail_at_host_journal_fault(
    path: &str,
    point: HostJournalFaultPoint,
    context: &'static str,
) -> Result<(), StorageError> {
    if take_host_journal_fault(path, point) {
        return Err(StorageError::InvalidData {
            context,
            reason: format!("injected host-journal fault at {point:?}"),
        });
    }
    Ok(())
}

#[cfg(test)]
fn fail_at_host_journal_transaction_fault(
    path: &str,
    point: HostJournalFaultPoint,
) -> Result<(), FrankenError> {
    if take_host_journal_fault(path, point) {
        return Err(FrankenError::Internal(format!(
            "injected host-journal transaction fault at {point:?}"
        )));
    }
    Ok(())
}

