    #[test]
    fn append_run_rejects_an_existing_run_id_even_when_provenance_matches()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-append-requires-new-run-id");
        let path_string = path.to_string_lossy().to_string();
        let manifest = unattributed_manifest_at(RunId::new(0x202), 202);
        let mut first = StoragePipeline::create_new_file_for_run(&path_string, manifest.clone())?;
        first.shutdown()?;

        let error = match StoragePipeline::append_run(&path_string, manifest) {
            Err(error) => error,
            Ok(mut unexpected) => {
                unexpected.shutdown()?;
                return Err("append_run accepted an already registered RunId".into());
            }
        };
        assert!(
            error
                .to_string()
                .contains("append_run requires a new independent RunId"),
            "unexpected duplicate-run error: {error}"
        );
        let catalog = StorageReader::catalog_page(&path_string, 0, 8)?;
        assert_eq!(catalog.len(), 1);
        assert_eq!(catalog[0].run_id, RunId::new(0x202));
        Ok(())
    }

    #[test]
    fn catalog_validates_only_the_requested_bounded_page() -> Result<(), Box<dyn std::error::Error>>
    {
        let path = temp_db_path("storage-bounded-run-catalog");
        let path_string = path.to_string_lossy().to_string();
        let older_run = RunId::new(0x301);
        let newer_run = RunId::new(0x302);

        let mut first = StoragePipeline::create_new_file_for_run(
            &path_string,
            unattributed_manifest_at(older_run, 301),
        )?;
        first.shutdown()?;
        let mut second =
            StoragePipeline::append_run(&path_string, unattributed_manifest_at(newer_run, 302))?;
        second.shutdown()?;

        let connection = Connection::open(&path_string)?;
        connection.execute_with_params(
            "UPDATE runs SET manifest_digest = 'blake3:tampered' WHERE run_id = ?1",
            &[sqlite_run_id(older_run)],
        )?;
        connection.close()?;

        let newest_page = StorageReader::catalog_page(&path_string, 0, 1)?;
        assert_eq!(newest_page.len(), 1);
        assert_eq!(newest_page[0].run_id, newer_run);

        let older_error = StorageReader::catalog_page(&path_string, 1, 1)
            .expect_err("the selected page must still validate its manifest");
        assert!(matches!(
            older_error,
            StorageError::InvalidData {
                context: "runs.manifest_digest",
                ..
            }
        ));
        Ok(())
    }

    fn sample_agent(energy: f32) -> AgentState {
        let data = AgentData {
            position: Position::new(12.0, 34.0),
            health: energy,
            ..AgentData::default()
        };

        let runtime = AgentRuntime {
            energy,
            ..AgentRuntime::default()
        };

        AgentState {
            id: scriptbots_core::AgentId::default(),
            identity: scriptbots_core::AgentIdentity {
                uid: AgentUid(1),
                spawn_ordinal: 0,
                birth_ordinal: None,
            },
            data,
            runtime,
        }
    }

    fn sample_batch(tick: u64, energy: f32) -> PersistenceBatch {
        PersistenceBatch {
            summary: TickSummary {
                tick: Tick(tick),
                agent_count: 1,
                births: 0,
                deaths: 0,
                total_energy: energy,
                average_energy: energy,
                average_health: 1.0,
                max_age: 0,
                spike_hits: 0,
            },
            epoch: 3,
            closed: false,
            metrics: vec![
                MetricSample::from_f32("total_energy", energy),
                MetricSample::from_f32("average_energy", energy),
                MetricSample::from_f32("average_health", 1.0),
            ],
            events: vec![PersistenceEvent::new(
                PersistenceEventKind::Custom("sample".into()),
                1,
            )],
            agents: vec![sample_agent(energy)],
            births: Vec::new(),
            deaths: Vec::new(),
            replay_events: Vec::new(),
            narrative_events: Vec::new(),
        }
    }

    fn sample_narrative_record(
        tick: u64,
        energy: f32,
        spike_hits: u32,
        config_revision: u64,
        history_capacity: u64,
    ) -> NarrativeInputRecordV1 {
        NarrativeInputRecordV1 {
            record_schema_version: NARRATIVE_INPUT_RECORD_V1_SCHEMA_VERSION,
            input: NarrativeInputV1 {
                schema_version: NARRATIVE_INPUT_V1_SCHEMA_VERSION,
                tick: Tick(tick),
                agent_count: 1,
                average_energy: energy,
                spike_hits,
            },
            config_revision,
            narrative_interval: 3,
            history_capacity,
            event_capacity: 32,
        }
    }

    fn sample_narrative_event(record: NarrativeInputRecordV1) -> ReplayEvent {
        ReplayEvent {
            agent_uid: None,
            position: None,
            counterpart: None,
            counterpart_position: None,
            kind: ReplayEventKind::NarrativeInputV1 { record },
        }
    }

    fn sample_narrative_batch(
        tick: u64,
        energy: f32,
        config_revision: u64,
        history_capacity: u64,
    ) -> PersistenceBatch {
        let mut batch = sample_batch(tick, energy);
        let spike_hits = u32::try_from(tick % 7).expect("bounded spike count");
        batch.summary.spike_hits = spike_hits;
        batch
            .replay_events
            .push(sample_narrative_event(sample_narrative_record(
                tick,
                energy,
                spike_hits,
                config_revision,
                history_capacity,
            )));
        batch
    }

    fn sample_narrative_span_batch(
        first_tick: u64,
        terminal_tick: u64,
        config_revision: u64,
        history_capacity: u64,
    ) -> PersistenceBatch {
        assert!(
            first_tick > 0 && first_tick <= terminal_tick,
            "narrative fixture span must be nonempty and begin after tick zero"
        );
        let mut batch = sample_batch(terminal_tick, 1.0);
        batch.summary.spike_hits = u32::try_from(terminal_tick % 7).expect("bounded spike count");
        batch
            .replay_events
            .extend((first_tick..=terminal_tick).map(|tick| {
                sample_narrative_event(sample_narrative_record(
                    tick,
                    1.0,
                    u32::try_from(tick % 7).expect("bounded spike count"),
                    config_revision,
                    history_capacity,
                ))
            }));
        batch
    }

    #[test]
    fn in_flight_reservation_refuses_atomic_counter_overflow() {
        let initial = usize::MAX - 4;
        let counter = Arc::new(AtomicUsize::new(initial));
        let would_be = InFlightPermit::try_acquire(&counter, 8, usize::MAX)
            .expect_err("an unrepresentable reservation must be refused");
        assert_eq!(would_be, usize::MAX);
        assert_eq!(counter.load(Ordering::SeqCst), initial);
    }

    fn synchronize_lifecycle_counts(batch: &mut PersistenceBatch) {
        let births = batch
            .births
            .iter()
            .filter(|record| record.origin == BirthOrigin::Born)
            .count();
        let deaths = batch.deaths.len();
        batch.summary.births = births;
        batch.summary.deaths = deaths;
        batch.events.retain(|event| {
            !matches!(
                &event.kind,
                PersistenceEventKind::Births | PersistenceEventKind::Deaths
            )
        });
        if births > 0 {
            batch
                .events
                .push(PersistenceEvent::new(PersistenceEventKind::Births, births));
        }
        if deaths > 0 {
            batch
                .events
                .push(PersistenceEvent::new(PersistenceEventKind::Deaths, deaths));
        }
    }

