    #[test]
    fn preparation_deadline_boundary_uses_before_exact_after_clock() {
        let configured = Duration::from_nanos(10);
        for (elapsed, should_expire) in [(9, false), (10, true), (11, true)] {
            let started = Instant::now();
            let mut stages = Vec::new();
            let result = {
                let mut clock = |stage| {
                    stages.push(stage);
                    if stage == PreparationStage::Start {
                        started
                    } else {
                        started + Duration::from_nanos(elapsed)
                    }
                };
                let mut deadline = PreparationDeadline::new(
                    &mut clock,
                    configured,
                    Arc::from(":boundary-test:"),
                    17,
                );
                deadline.checkpoint(PreparationStage::Measure, PreparationProgress::default())
            };
            assert_eq!(stages, [PreparationStage::Start, PreparationStage::Measure]);
            if should_expire {
                assert!(matches!(
                    result,
                    Err(StorageError::Worker(StorageWorkerError::Timeout {
                        operation: StorageOperation::Admit,
                        phase: StorageWaitPhase::Preparation,
                        tick: Some(17),
                        waited,
                        commit_state: FailureCommitState::NotAdmitted,
                        ..
                    })) if waited == configured
                ));
            } else {
                result.expect("a checkpoint one nanosecond before the deadline must pass");
            }
        }
    }

    #[test]
    fn preparation_deadline_covers_every_pre_enqueue_stage_without_side_effects() {
        let target_stages = [
            PreparationStage::Measure,
            PreparationStage::NarrativeMeasure,
            PreparationStage::Permit,
            PreparationStage::Materialize,
            PreparationStage::Validate,
            PreparationStage::Analytics,
            PreparationStage::Complete,
        ];
        for target in target_stages {
            let (tx, rx) = xchan::bounded(1);
            let sink = StorageSink {
                run_id: RunId::new(1),
                tx,
                analytics: AnalyticsSnapshotProvider::empty(),
                admission: Arc::new(Mutex::new(AdmissionState { open: true })),
                path: Arc::from(format!(":preparation-stage-{}:", target.as_str())),
                deadlines: StorageDeadlines {
                    preparation: Duration::from_nanos(10),
                    ..StorageDeadlines::default()
                },
                budget: PayloadBudget::default(),
                inflight_bytes: Arc::new(AtomicUsize::new(0)),
            };
            let payload = sample_batch(89, 8.9);
            let expected_estimate = estimate_batch_size(&payload);
            let started = Instant::now();
            let mut witnessed_target = false;
            let mut clock = |stage| {
                if stage == target {
                    witnessed_target = true;
                    started + Duration::from_nanos(10)
                } else {
                    started
                }
            };

            let error = sink
                .submit_with_receipt_using_clock(&payload, &mut clock)
                .expect_err("the selected preparation stage must hit the exact deadline");
            assert!(
                matches!(
                    error,
                    StorageError::Worker(StorageWorkerError::Timeout {
                        operation: StorageOperation::Admit,
                        phase: StorageWaitPhase::Preparation,
                        tick: Some(89),
                        waited,
                        commit_state: FailureCommitState::NotAdmitted,
                        ..
                    }) if waited == Duration::from_nanos(10)
                ),
                "stage {target:?} did not return the typed preparation refusal"
            );
            assert!(
                witnessed_target,
                "stage {target:?} was not reached under the preparation deadline"
            );
            assert_eq!(
                sink.inflight_bytes.load(Ordering::SeqCst),
                0,
                "stage {target:?} leaked an in-flight permit"
            );
            assert!(
                matches!(rx.try_recv(), Err(xchan::TryRecvError::Empty)),
                "stage {target:?} enqueued a worker command"
            );
            assert_eq!(
                sink.analytics.snapshot().watermarks,
                PersistenceWatermarks::default(),
                "stage {target:?} minted an identity or advanced a watermark"
            );
            assert_eq!(
                estimate_batch_size(&payload),
                expected_estimate,
                "stage {target:?} changed the retained retry payload"
            );
            assert_eq!(payload.summary.tick.0, 89);
        }
    }

    #[test]
    fn preparation_deadline_interrupts_nested_replay_serialization_without_permit_leak() {
        let (tx, rx) = xchan::bounded(1);
        let sink = StorageSink {
            run_id: RunId::new(1),
            tx,
            analytics: AnalyticsSnapshotProvider::empty(),
            admission: Arc::new(Mutex::new(AdmissionState { open: true })),
            path: Arc::from(":nested-replay-deadline:"),
            deadlines: StorageDeadlines {
                preparation: Duration::from_nanos(10),
                ..StorageDeadlines::default()
            },
            budget: PayloadBudget::default(),
            inflight_bytes: Arc::new(AtomicUsize::new(0)),
        };
        let mut payload = sample_batch(90, 9.0);
        payload.replay_events.push(ReplayEvent {
            agent_uid: Some(AgentUid(1)),
            position: None,
            counterpart: None,
            counterpart_position: None,
            kind: ReplayEventKind::BrainOutputs {
                outputs: vec![0.25; 4_096],
            },
        });
        let started = Instant::now();
        let mut replay_checkpoints = 0usize;
        let mut clock = |stage| {
            if stage == PreparationStage::ReplaySerialization {
                replay_checkpoints = replay_checkpoints.saturating_add(1);
            }
            if replay_checkpoints >= 3 {
                started + Duration::from_nanos(10)
            } else {
                started
            }
        };

        let error = sink
            .submit_with_receipt_using_clock(&payload, &mut clock)
            .expect_err("the third nested replay checkpoint must hit the exact deadline");
        assert!(matches!(
            error,
            StorageError::Worker(StorageWorkerError::Timeout {
                operation: StorageOperation::Admit,
                phase: StorageWaitPhase::Preparation,
                tick: Some(90),
                waited,
                commit_state: FailureCommitState::NotAdmitted,
                ..
            }) if waited == Duration::from_nanos(10)
        ));
        assert_eq!(replay_checkpoints, 3);
        assert_eq!(
            sink.inflight_bytes.load(Ordering::SeqCst),
            0,
            "a deadline after permit acquisition must release the permit"
        );
        assert!(matches!(rx.try_recv(), Err(xchan::TryRecvError::Empty)));
        assert_eq!(
            sink.analytics.snapshot().watermarks,
            PersistenceWatermarks::default(),
            "pre-enqueue refusal must not publish an identity or watermark"
        );
        assert!(matches!(
            &payload.replay_events[0].kind,
            ReplayEventKind::BrainOutputs { outputs } if outputs.len() == 4_096
        ));
    }

    #[test]
    fn preparation_deadline_file_pipeline_e2e_preserves_exact_retry()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-preparation-deadline-e2e");
        let path_string = path.to_string_lossy().to_string();
        let mut pipeline = StoragePipeline::create_unattributed_file_with_thresholds(
            &path_string,
            64,
            4_096,
            1_024,
            1_024,
        )?;
        let mut deadline_sink = pipeline.sink();
        deadline_sink.deadlines.preparation = Duration::from_nanos(10);
        let payload = sample_batch(91, 9.1);
        let (scientific_bytes, scientific_records) = estimate_batch_size(&payload);
        let started = Instant::now();
        let mut clock = |stage| {
            if stage == PreparationStage::Materialize {
                started + Duration::from_nanos(10)
            } else {
                started
            }
        };

        let refusal = deadline_sink
            .submit_with_receipt_using_clock(&payload, &mut clock)
            .expect_err("materialization at the exact deadline must be refused");
        assert!(matches!(
            refusal,
            StorageError::Worker(StorageWorkerError::Timeout {
                operation: StorageOperation::Admit,
                phase: StorageWaitPhase::Preparation,
                tick: Some(91),
                waited,
                commit_state: FailureCommitState::NotAdmitted,
                ..
            }) if waited == Duration::from_nanos(10)
        ));
        assert_eq!(pipeline.inflight_bytes(), 0);
        let reader = StorageReader::open(&path_string)?;
        assert_eq!(
            reader.persistence_watermarks()?,
            PersistenceWatermarks::default()
        );
        assert_eq!(reader.run_ledger_summary()?.tick_count, 0);
        reader.close()?;
        println!(
            "{}",
            json!({
                "schema": "scriptbots.persistence-preparation.evidence.v1",
                "phase": "refusal",
                "stage": "materialize",
                "deadline": "10ns",
                "scientific_bytes": scientific_bytes,
                "scientific_records": scientific_records,
                "payload_key": format!("tick-91-bytes-{scientific_bytes}"),
                "identity_state": "unassigned",
                "disposition": "not_admitted",
                "receipt": Value::Null,
                "batch_id": Value::Null,
                "tick": 91,
                "durable_tick_count": 0
            })
        );

        let healthy_started = Instant::now();
        let mut healthy_clock = |stage| {
            if stage == PreparationStage::Start {
                healthy_started
            } else {
                healthy_started + Duration::from_nanos(9)
            }
        };
        let receipt =
            deadline_sink.submit_with_receipt_using_clock(&payload, &mut healthy_clock)?;
        let duplicate =
            deadline_sink.submit_with_receipt_using_clock(&payload, &mut healthy_clock)?;
        assert_eq!(receipt.guarantee, PersistenceGuarantee::Durable);
        assert_eq!(duplicate.guarantee, receipt.guarantee);
        assert_eq!(
            duplicate.batch_id, receipt.batch_id,
            "the exact retry must reuse its durable identity"
        );
        let flush = pipeline.flush_and_wait()?;
        assert_eq!(flush.watermarks.durable, Some(receipt.batch_id));
        pipeline.shutdown()?;

        let reader = StorageReader::open(&path_string)?;
        let ledger = reader.run_ledger_summary()?;
        assert_eq!(ledger.tick_count, 1);
        assert_eq!(ledger.latest_tick.map(|tick| tick.tick), Some(91));
        let final_watermarks = reader.persistence_watermarks()?;
        assert_eq!(final_watermarks.admitted, Some(receipt.batch_id));
        assert_eq!(final_watermarks.applied, Some(receipt.batch_id));
        assert_eq!(final_watermarks.durable, Some(receipt.batch_id));
        reader.close()?;
        let receipt_label = match receipt.guarantee {
            PersistenceGuarantee::CommittedVolatile => "committed_volatile",
            PersistenceGuarantee::Durable => "durable",
        };
        println!(
            "{}",
            json!({
                "schema": "scriptbots.persistence-preparation.evidence.v1",
                "phase": "retry",
                "stage": "outbox_admission",
                "deadline": "10ns",
                "scientific_bytes": scientific_bytes,
                "scientific_records": scientific_records,
                "payload_key": format!("tick-91-bytes-{scientific_bytes}"),
                "identity_state": "assigned",
                "disposition": "admitted",
                "receipt": receipt_label,
                "batch_id": receipt.batch_id.get(),
                "tick": 91,
                "durable_tick_count": ledger.tick_count
            })
        );
        Ok(())
    }

    #[test]
    fn invalid_deadline_configuration_is_rejected_without_panicking()
    -> Result<(), Box<dyn std::error::Error>> {
        let deadlines = StorageDeadlines {
            startup_ack: Duration::MAX,
            ..StorageDeadlines::default()
        };
        let error = match StoragePipeline::unattributed_memory_with_thresholds_and_deadlines(
            64, 4096, 1024, 1024, deadlines,
        ) {
            Ok(mut pipeline) => {
                pipeline.shutdown()?;
                return Err("invalid deadline unexpectedly created a pipeline".into());
            }
            Err(error) => error,
        };
        assert!(matches!(
            error,
            StorageError::InvalidData {
                context: "storage.deadlines",
                ..
            }
        ));
        let preparation_error =
            match StoragePipeline::unattributed_memory_with_thresholds_and_deadlines(
                64,
                4096,
                1024,
                1024,
                StorageDeadlines {
                    preparation: Duration::ZERO,
                    ..StorageDeadlines::default()
                },
            ) {
                Ok(mut pipeline) => {
                    pipeline.shutdown()?;
                    return Err("zero preparation deadline unexpectedly created a pipeline".into());
                }
                Err(error) => error,
            };
        assert!(matches!(
            preparation_error,
            StorageError::InvalidData {
                context: "storage.deadlines",
                ..
            }
        ));
        Ok(())
    }

    #[test]
    fn startup_timeout_retains_path_ownership_until_supervised_join()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-startup-timeout-lease");
        let path_string = path.to_string_lossy().to_string();
        let (entered, release) = register_startup_pause(&path_string);
        let deadlines = StorageDeadlines {
            startup_ack: Duration::from_millis(100),
            ..short_deadlines()
        };
        let first_error =
            match StoragePipeline::create_unattributed_file_with_thresholds_and_deadlines(
                &path_string,
                64,
                4096,
                1024,
                1024,
                deadlines,
            ) {
                Ok(mut pipeline) => {
                    pipeline.shutdown()?;
                    return Err("startup pause did not trigger its deadline".into());
                }
                Err(error) => error,
            };
        assert!(matches!(
            first_error,
            StorageError::Worker(StorageWorkerError::Timeout {
                operation: StorageOperation::Startup,
                phase: StorageWaitPhase::Acknowledgement,
                ..
            })
        ));
        entered.recv_timeout(Duration::from_secs(2))?;

        let second_error = match StoragePipeline::with_target_and_deadlines(
            StorageTarget::RecoverExisting(path_string.clone()),
            64,
            4096,
            1024,
            1024,
            deadlines,
        ) {
            Ok(mut pipeline) => {
                pipeline.shutdown()?;
                return Err("second writer bypassed the timed-out startup lease".into());
            }
            Err(error) => error,
        };
        assert!(
            second_error
                .to_string()
                .contains("another ScriptBots writer")
        );
        release.send(())?;

        let retry_deadline = Instant::now() + Duration::from_secs(5);
        let retry_deadlines = short_deadlines();
        loop {
            match StoragePipeline::with_target_and_deadlines(
                StorageTarget::RecoverExisting(path_string.clone()),
                64,
                4096,
                1024,
                1024,
                retry_deadlines,
            ) {
                Ok(mut pipeline) => {
                    pipeline.shutdown()?;
                    break;
                }
                Err(error) => {
                    if Instant::now() >= retry_deadline {
                        return Err(format!(
                            "supervised startup join never released the path lease: {error}"
                        )
                        .into());
                    }
                    thread::sleep(Duration::from_millis(10));
                }
            }
        }
        Ok(())
    }

    #[test]
    fn writer_path_lease_rejects_a_second_live_writer_and_releases_on_shutdown()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-writer-path-lease");
        let path_string = path.to_string_lossy().to_string();
        let mut first = StoragePipeline::create_unattributed_file(&path_string)?;
        let error = match StoragePipeline::recover_existing(&path_string) {
            Ok(mut second) => {
                second.shutdown()?;
                return Err("second writer unexpectedly acquired the same database".into());
            }
            Err(error) => error,
        };
        assert!(error.to_string().contains("another ScriptBots writer"));
        first.shutdown()?;

        let mut after_shutdown = StoragePipeline::recover_existing(&path_string)?;
        after_shutdown.shutdown()?;
        Ok(())
    }

    struct WriterLeaseChild {
        child: Child,
    }

    impl WriterLeaseChild {
        fn wait_until_exit(
            &mut self,
            context: &str,
        ) -> Result<ExitStatus, Box<dyn std::error::Error>> {
            let deadline = Instant::now() + Duration::from_secs(10);
            loop {
                if let Some(status) = self.child.try_wait()? {
                    return Ok(status);
                }
                if Instant::now() >= deadline {
                    self.child.kill()?;
                    let status = self.child.wait()?;
                    return Err(format!(
                        "writer-lease child timed out during {context}; terminated with {status}"
                    )
                    .into());
                }
                thread::sleep(Duration::from_millis(10));
            }
        }

        fn force_terminate(&mut self) -> Result<ExitStatus, Box<dyn std::error::Error>> {
            if let Some(status) = self.child.try_wait()? {
                return Ok(status);
            }
            self.child.kill()?;
            Ok(self.child.wait()?)
        }
    }

    impl Drop for WriterLeaseChild {
        fn drop(&mut self) {
            if self.child.try_wait().ok().flatten().is_none() {
                let _ = self.child.kill();
                let _ = self.child.wait();
            }
        }
    }

    fn spawn_writer_lease_child(
        path: &str,
        mode: &str,
        ready_path: Option<&Path>,
    ) -> Result<WriterLeaseChild, Box<dyn std::error::Error>> {
        let mut command = Command::new(std::env::current_exe()?);
        command
            .args([
                "--exact",
                "tests::storage_writer_lease_child",
                "--nocapture",
            ])
            .env("SCRIPTBOTS_STORAGE_WRITER_LEASE_CHILD", mode)
            .env("SCRIPTBOTS_STORAGE_WRITER_LEASE_PATH", path)
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit());
        if let Some(ready_path) = ready_path {
            command
                .env("SCRIPTBOTS_STORAGE_WRITER_LEASE_READY", ready_path)
                .stdin(Stdio::piped());
        } else {
            command.stdin(Stdio::null());
        }
        Ok(WriterLeaseChild {
            child: command.spawn()?,
        })
    }

    fn wait_for_writer_lease_child(
        child: &mut WriterLeaseChild,
        ready_path: &Path,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if ready_path.try_exists()? {
                return Ok(());
            }
            if let Some(status) = child.child.try_wait()? {
                return Err(format!(
                    "writer-lease owner exited before readiness with status {status}"
                )
                .into());
            }
            if Instant::now() >= deadline {
                let status = child.force_terminate()?;
                return Err(format!(
                    "writer-lease owner did not become ready; terminated with status {status}"
                )
                .into());
            }
            thread::sleep(Duration::from_millis(10));
        }
    }

    fn release_writer_lease_child(
        child: &mut WriterLeaseChild,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let mut stdin = child
            .child
            .stdin
            .take()
            .ok_or_else(|| std::io::Error::other("writer-lease child stdin was not piped"))?;
        stdin.write_all(b"\n")?;
        drop(stdin);
        let status = child.wait_until_exit("graceful shutdown")?;
        if !status.success() {
            return Err(format!("writer-lease owner failed during shutdown: {status}").into());
        }
        Ok(())
    }

    fn run_writer_lease_child(path: &str, mode: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut child = spawn_writer_lease_child(path, mode, None)?;
        let status = child.wait_until_exit(mode)?;
        if !status.success() {
            return Err(format!("writer-lease child mode {mode:?} failed: {status}").into());
        }
        Ok(())
    }

    #[test]
    fn storage_writer_lease_child() -> Result<(), Box<dyn std::error::Error>> {
        let Ok(mode) = std::env::var("SCRIPTBOTS_STORAGE_WRITER_LEASE_CHILD") else {
            return Ok(());
        };
        let path = std::env::var("SCRIPTBOTS_STORAGE_WRITER_LEASE_PATH")?;
        match mode.as_str() {
            "pipeline-owner" => {
                let mut pipeline = StoragePipeline::recover_existing(&path)?;
                let ready_path = std::env::var("SCRIPTBOTS_STORAGE_WRITER_LEASE_READY")?;
                fs::write(ready_path, b"ready")?;
                std::io::stdin().read_exact(&mut [0_u8])?;
                pipeline.shutdown()?;
            }
            "lease-only-owner" => {
                let _lease = StorageWriterLease::acquire(&path)?.ok_or_else(|| {
                    std::io::Error::other("file-backed path did not create a writer lease")
                })?;
                let ready_path = std::env::var("SCRIPTBOTS_STORAGE_WRITER_LEASE_READY")?;
                fs::write(ready_path, b"ready")?;
                std::io::stdin().read_exact(&mut [0_u8])?;
            }
            "expect-refusal" => {
                let expected_lock_path = storage_writer_lock_path(&path).display().to_string();
                let error = match StoragePipeline::recover_existing(&path) {
                    Ok(mut pipeline) => {
                        pipeline.shutdown()?;
                        return Err("second process unexpectedly acquired the writer lease".into());
                    }
                    Err(error) => error,
                };
                match error {
                    StorageError::Worker(StorageWorkerError::WriterLeaseHeld {
                        operation,
                        path: refused_path,
                        lock_path,
                        tick,
                        commit_state,
                    }) => {
                        assert_eq!(operation, StorageOperation::Startup);
                        assert_eq!(refused_path, path);
                        assert_eq!(lock_path, expected_lock_path);
                        assert_eq!(tick, None);
                        assert_eq!(commit_state, FailureCommitState::NotAdmitted);
                    }
                    other => {
                        return Err(format!(
                            "second writer returned an untyped or unexpected error: {other}"
                        )
                        .into());
                    }
                }
            }
            "expect-open" => {
                let mut pipeline = StoragePipeline::recover_existing(&path)?;
                pipeline.shutdown()?;
            }
            other => return Err(format!("unknown writer-lease child mode {other:?}").into()),
        }
        Ok(())
    }

    #[test]
