        let mut recovered = StoragePipeline::recover_existing(&path_string)?;
        let shutdown = recovered.shutdown()?;
        assert_eq!(shutdown.watermarks.durable, ids.last().copied());
        let reader = StorageReader::open(&path_string)?;
