    #[test]
    fn rolled_back_application_keeps_the_exact_outbox_for_recovery()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-outbox-rollback-recovery");
        let path_string = path.to_string_lossy().to_string();
        let batch = sample_batch(41, 4.1);
        let prepared = PreparedPersistenceBatch::from_batch(&batch)?;
        let mut interrupted = create_file_storage(&path_string)?;
        let (admission, newly_admitted) =
            interrupted.stage_outbox(prepared.tick, &prepared.storage)?;
        assert!(newly_admitted);
        assert!(!interrupted.enqueue_staged(admission.batch_id, prepared.storage)?);
        let canonical_metrics_sql: String = interrupted
            .connection()?
            .query_row(
                "SELECT sql FROM sqlite_schema
                 WHERE type = 'table' AND name = 'metrics'",
            )?
            .get_typed(0)?;
        let canonical_metrics_index_sql: String = interrupted
            .connection()?
            .query_row(
                "SELECT sql FROM sqlite_schema
                 WHERE type = 'index' AND name = 'metrics_run_name_tick_index'",
            )?
            .get_typed(0)?;
        interrupted.connection()?.execute("DROP TABLE metrics")?;
        let failure = interrupted
            .flush()
            .expect_err("missing table must roll back the scientific-table transaction");
        assert!(matches!(
            failure,
            StorageError::Transaction {
                commit_state: FailureCommitState::RolledBack,
                ..
            }
        ));
        let tick_count: i64 = interrupted
            .connection()?
            .query_row_with_params(
                "SELECT COUNT(*) FROM tick_summaries WHERE run_id = ?1",
                &[sqlite_run_id(interrupted.run_id)],
            )?
            .get_typed(0)?;
        assert_eq!(tick_count, 0);
        assert_eq!(
            interrupted.persistence_watermarks()?.applied,
            None,
            "rolled-back application advanced its watermark"
        );
        interrupted.abandon_after_error();

        let repair = Connection::open(&path_string)?;
        repair.execute(&canonical_metrics_sql)?;
        repair.execute(&canonical_metrics_index_sql)?;
        repair.close()?;
        let mut recovered = StoragePipeline::recover_existing(&path_string)?;
        let shutdown = recovered.shutdown()?;
        assert_eq!(shutdown.watermarks.durable, Some(admission.batch_id));
        let mut durable = recover_file_storage(&path_string)?;
        assert_eq!(durable.max_tick()?, Some(41));
        assert_integrity(&durable)?;
        durable.close()?;
        Ok(())
    }

    #[test]
    fn exact_duplicate_admission_reuses_one_batch_identity()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-outbox-duplicate");
        let path_string = path.to_string_lossy().to_string();
        let mut batch = sample_batch(51, 5.1);
        let mut birth = sample_birth(51, 17, BirthOrigin::Born);
        birth.spawn_ordinal = 41;
        birth.birth_ordinal = Some(73);
        batch.births.push(birth);
        synchronize_lifecycle_counts(&mut batch);
        let prepared = PreparedPersistenceBatch::from_batch(&batch)?;
        let mut storage = create_file_storage(&path_string)?;
        let (first, first_is_new) = storage.stage_outbox(prepared.tick, &prepared.storage)?;
        let (duplicate, duplicate_is_new) =
            storage.stage_outbox(prepared.tick, &prepared.storage)?;
        assert!(first_is_new);
        assert!(!duplicate_is_new);
        assert_eq!(duplicate.batch_id, first.batch_id);
        assert!(!storage.enqueue_staged(first.batch_id, prepared.storage)?);
        storage.flush()?;
        let watermarks = storage.finalize_applied_outbox()?;
        assert_eq!(watermarks.durable, Some(first.batch_id));
        let ledger_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM storage_batch_ledger")?
            .get_typed(0)?;
        assert_eq!(ledger_count, 1);

        assert_integrity(&storage)?;
        storage.close()?;
        let prepared = PreparedPersistenceBatch::from_batch(&batch)?;
        let mut reopened = recover_file_storage(&path_string)?;
        let (duplicate_after_reopen, duplicate_after_reopen_is_new) =
            reopened.stage_outbox(prepared.tick, &prepared.storage)?;
        assert!(!duplicate_after_reopen_is_new);
        assert_eq!(duplicate_after_reopen.batch_id, first.batch_id);

        let conflicting = Storage::prepare_batch(&sample_batch(51, 99.0))?;
        assert!(matches!(
            reopened.stage_outbox(51, &conflicting),
            Err(StorageError::InvalidData {
                context: "storage_batch_ledger.payload_digest",
                ..
            })
        ));
        let ledger_count: i64 = reopened
            .connection()?
            .query_row("SELECT COUNT(*) FROM storage_batch_ledger")?
            .get_typed(0)?;
        assert_eq!(ledger_count, 1);
        assert_integrity(&reopened)?;
        reopened.close()?;
        Ok(())
    }

    #[test]
    fn public_file_persist_preserves_one_identity_and_monotonic_watermarks()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-direct-persist-outbox");
        let path_string = path.to_string_lossy().to_string();
        let batch = sample_batch(52, 5.2);
        let mut storage = create_file_storage(&path_string)?;

        storage.persist(&batch)?;
        let admitted = storage.persistence_watermarks()?;
        let Some(batch_id) = admitted.admitted else {
            return Err("direct persist did not assign a stable batch identity".into());
        };
        assert_eq!(admitted.applied, None);
        assert_eq!(admitted.durable, None);

        storage.persist(&batch)?;
        assert_eq!(storage.persistence_watermarks()?, admitted);
        let ledger_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM storage_batch_ledger")?
            .get_typed(0)?;
        let outbox_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM storage_outbox")?
            .get_typed(0)?;
        assert_eq!(ledger_count, 1);
        assert_eq!(outbox_count, 1);

        storage.flush()?;
        let applied = storage.persistence_watermarks()?;
        assert_eq!(applied.admitted, Some(batch_id));
        assert_eq!(applied.applied, Some(batch_id));
        assert_eq!(applied.durable, None);
        storage.close()?;

        let mut reopened = recover_file_storage(&path_string)?;
        let durable = reopened.persistence_watermarks()?;
        assert_eq!(durable.admitted, Some(batch_id));
        assert_eq!(durable.applied, Some(batch_id));
        assert_eq!(durable.durable, Some(batch_id));

        reopened.persist(&batch)?;
        assert_eq!(reopened.persistence_watermarks()?, durable);
        let conflicting = sample_batch(52, 99.0);
        assert!(matches!(
            reopened.persist(&conflicting),
            Err(StorageError::InvalidData {
                context: "storage_batch_ledger.payload_digest",
                ..
            })
        ));
        assert_eq!(reopened.persistence_watermarks()?, durable);
        let tick_count: i64 = reopened
            .connection()?
            .query_row_with_params(
                "SELECT COUNT(*) FROM tick_summaries WHERE run_id = ?1 AND tick = 52",
                &[sqlite_run_id(reopened.run_id)],
            )?
            .get_typed(0)?;
        assert_eq!(tick_count, 1);

        reopened.close()?;
        let _ = fs::remove_file(path);
        Ok(())
    }

    /// `bd-x8wf`: `stage_outbox` is the only method that mints a batch identity and
    /// CAS-advances the admitted watermark, and the storage worker calls it directly
    /// rather than through `persist`. It must therefore carry the same fail-closed guard
    /// as its siblings: after a terminal failure no caller — public or worker — can append
    /// another identity to the ledger.
    #[test]
    fn a_terminally_failed_writer_refuses_to_admit_another_batch_identity()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-terminal-admission-guard");
        let path_string = path.to_string_lossy().to_string();
        let mut storage = create_file_storage(&path_string)?;
        storage.persist(&sample_batch(61, 6.1))?;
        let before = storage.persistence_watermarks()?;
        assert!(before.admitted.is_some());

        // Force a terminal, non-transient flush failure: the scientific table the buffered
        // batch needs no longer exists, so the application transaction rolls back whole.
        storage.connection()?.execute("DROP TABLE metrics")?;
        let failure = storage
            .flush()
            .expect_err("a missing scientific table must fail the application transaction");
        assert!(
            matches!(
                failure,
                StorageError::Transaction {
                    commit_state: FailureCommitState::RolledBack,
                    ..
                }
            ),
            "expected a rolled-back transaction failure, got {failure}"
        );

        // The worker's direct admission entry point is fail-closed, not only `persist`.
        let next = Storage::prepare_batch(&sample_batch(62, 6.2))?;
        assert!(
            matches!(
                storage.stage_outbox(62, &next),
                Err(StorageError::TerminallyFailed)
            ),
            "stage_outbox admitted a batch on a terminally failed writer"
        );
        assert!(matches!(
            storage.persist(&sample_batch(62, 6.2)),
            Err(StorageError::TerminallyFailed)
        ));
        assert!(matches!(
            storage.flush(),
            Err(StorageError::TerminallyFailed)
        ));

        assert_eq!(
            storage.persistence_watermarks()?,
            before,
            "a refused admission advanced a watermark"
        );
        let ledger_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM storage_batch_ledger")?
            .get_typed(0)?;
        assert_eq!(
            ledger_count, 1,
            "a terminally failed writer minted another batch identity"
        );
        storage.abandon_after_error();
        let _ = fs::remove_file(path);
        Ok(())
    }

    /// `bd-jjxe`: a cleanly closed run must leave no sidecar, so that a sidecar's existence
    /// unambiguously means the previous run did not close cleanly.
    ///
    /// Before this, `Connection::close`'s passive checkpoint left the `-wal` in place, and
    /// `ensure_no_storage_sidecars` then refused the same path for a new run — a clean
    /// shutdown poisoned the next open. The guard is correct and deliberately cannot tell a
    /// clean close from a crash, so the fix is that a clean close leaves nothing to find.
    #[test]
    fn a_clean_close_leaves_no_sidecar_to_refuse() -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-clean-close-sidecars");
        let path_string = path.to_string_lossy().to_string();

        let mut storage = create_file_storage(&path_string)?;
        for (tick, energy) in [(1_u64, 1.5_f32), (2, 3.0), (3, 4.5), (4, 6.0)] {
            storage.persist(&sample_batch(tick, energy))?;
        }
        storage.flush()?;
        storage.close()?;

        for suffix in ["-wal", "-shm", "-journal", "-wal-fec"] {
            let sidecar = PathBuf::from(format!("{path_string}{suffix}"));
            // Report the length too: a zero-length remnant and a full-size one are very
            // different failures. The first means the checkpoint worked and only the file
            // survived; the second means the WAL was never folded in at all.
            let length = fs::metadata(&sidecar).map(|meta| meta.len());
            assert!(
                !sidecar.exists(),
                "a clean close left {} behind ({length:?} bytes), which a later new-run \
                 open refuses",
                sidecar.display()
            );
        }

        // A new-run open of this path is still refused, and that is correct — reusing a
        // prior run's database is forbidden regardless of sidecars. What matters is *which*
        // refusal fires: it must be the existing-database one, never the stale-sidecar one,
        // because the sidecar reason is what a clean shutdown used to trigger spuriously.
        // `Storage` is not `Debug`, so take the error side rather than `expect_err`.
        let refusal = create_file_storage(&path_string)
            .err()
            .expect("a new run must still refuse an existing database path");
        let reason = match &refusal {
            StorageError::InvalidTarget { reason, .. } => reason.clone(),
            _ => String::new(),
        };
        assert!(
            !reason.is_empty(),
            "expected an InvalidTarget refusal, got {refusal:?}"
        );
        assert!(
            !reason.contains("sidecar"),
            "a cleanly closed run was refused for a stale sidecar, which is the bug: {reason}"
        );
        assert!(
            reason.contains("existing database path"),
            "expected the existing-database refusal, got {reason}"
        );

        // The data survived the truncating checkpoint and the sidecar removal: recovery
        // opens the same file and still sees every admitted batch. This is the safety half
        // of the fix — emptying and deleting the log must never cost committed rows.
        let mut recovered = StoragePipeline::recover_existing(&path_string)?;
        let shutdown = recovered.shutdown()?;
        assert_eq!(
            shutdown.watermarks.durable.map(PersistenceBatchId::get),
            Some(4),
            "recovery after a truncating close lost admitted batches"
        );
        let reader = StorageReader::open(&path_string)?;
        assert_eq!(
            reader.max_tick()?,
            Some(4),
            "recovery after a truncating close lost scientific rows"
        );
        reader.close()?;

        let _ = fs::remove_file(path);
        Ok(())
    }

    fn assert_invalid_data_context<T: std::fmt::Debug>(
        result: Result<T, StorageError>,
        expected: &'static str,
    ) {
        let matches_expected = matches!(
            &result,
            Err(StorageError::InvalidData { context, .. }) if *context == expected
        );
        assert!(
            matches_expected,
            "expected InvalidData for {expected}, got {result:?}"
        );
    }

    /// The real write path attributes each island's rows to that island (bd-16g.5.5).
    ///
    /// The V15 schema tests prove the TABLES can hold eight islands; this proves the WRITER
    /// puts them there. It goes through `persist_for_island` and the normal flush rather than
    /// direct SQL, so it fails if any of the seven insert statements drops the column or binds
    /// it positionally in the wrong slot.
    ///
    /// `COUNT(DISTINCT island_id)` MUST EQUAL THE ISLAND COUNT, NOT MERELY BE NON-ZERO. A
    /// writer that stamped a constant island onto every row would leave the column present,
    /// non-null and indexed on every table, and would satisfy any weaker check while
    /// collapsing the partition the column exists to preserve.
    ///
    /// ISLANDS WRITE AT DISTINCT TICKS HERE, AND THAT IS A LIMITATION RATHER THAN A CHOICE.
    /// The outbox batch ledger admits one batch per `(run_id, tick)`, so eight islands
    /// submitting the same tick as separate batches collide ABOVE the science tables, in
    /// admission. `same_tick_multi_island_submission_is_refused_by_the_batch_ledger` pins that
    /// boundary exactly; until a barrier fuses all islands into one batch, this is the
    /// strongest end-to-end partition proof the writer can support.
    #[test]
    fn persist_for_island_partitions_every_table_by_its_island()
    -> Result<(), Box<dyn std::error::Error>> {
        const ISLANDS: i64 = 8;

        let path = temp_db_path("storage-island-partition");
        let path_string = path.to_string_lossy().to_string();
        let mut storage =
            Storage::create_unattributed_file_with_thresholds(&path_string, 1, 1, 1, 1)?;

        for island in 0..ISLANDS {
            let island_id = IslandId(u32::try_from(island)?);
            // Two ticks per island, disjoint across islands, because admission is keyed by tick.
            let arrival_tick = 42 + u64::try_from(island)? * 2;
            let death_tick = arrival_tick + 1;

            let mut arrival = sample_batch(arrival_tick, 5.5);
            // Every island reuses the SAME agent_uid and spawn/birth ordinals, because every
            // island mints them from its own private counter (bd-8jlj). Under V14's run-scoped
            // unique indexes the second island here was rejected outright; that these all land
            // is the write-path half of what V15's lifted indexes made possible.
            // Distinct uids per island, which is NOT what an archipelago produces. Each island
            // mints uids from its own counter, so island 0 and island 1 both hold agent 1 --
            // and V15's lifted unique indexes make that storable. The Rust-side ancestry guard
            // still refuses it because it reasons run-scoped;
            // `ancestry_coherence_is_run_scoped_and_refuses_per_island_uid_reuse` pins that,
            // and this test sidesteps it so it can measure the per-table partition instead.
            let uid = u64::try_from(island)? + 1;
            arrival.births = vec![sample_birth(arrival_tick, uid, BirthOrigin::Born)];
            // The writer cross-checks the summary against the record streams AND against the
            // canonical event rows, so all three have to agree or the batch is refused before
            // any island logic runs.
            arrival.summary.births = 1;
            arrival
                .events
                .push(PersistenceEvent::new(PersistenceEventKind::Births, 1));
            storage.persist_for_island(&arrival, island_id)?;

            // Deaths land a tick later because an ancestry guard refuses a death that does not
            // FOLLOW its arrival. That guard is run-scoped rather than island-scoped, which is
            // recorded on bd-16g.5.5: with per-island uid counters, island 0's agent 1 and
            // island 7's agent 1 are different organisms that it currently treats as one.
            let mut departure = sample_batch(death_tick, 5.5);
            departure.deaths = vec![sample_death(death_tick, uid, DeathCause::Starvation)];
            departure.summary.deaths = 1;
            departure
                .events
                .push(PersistenceEvent::new(PersistenceEventKind::Deaths, 1));
            storage.persist_for_island(&departure, island_id)?;
        }
        storage.flush()?;

        let connection = storage.connection()?;
        for table in [
            "tick_summaries",
            "metrics",
            "events",
            "agents",
            "births",
            "deaths",
        ] {
            let distinct: i64 = connection
                .query_row_with_params(
                    &format!("SELECT COUNT(DISTINCT island_id) FROM {table} WHERE run_id = ?1"),
                    &[sqlite_run_id(storage.run_id)],
                )?
                .get_typed(0)?;
            assert_eq!(
                distinct, ISLANDS,
                "{table} collapsed its island partition: the writer stamped {distinct} distinct \
                 island(s) across {ISLANDS} islands"
            );

            // Every island must be individually addressable, not merely collectively distinct:
            // a writer that permuted the labels would still produce ISLANDS distinct values.
            for island in 0..ISLANDS {
                let rows: i64 = connection
                    .query_row_with_params(
                        &format!(
                            "SELECT COUNT(*) FROM {table} WHERE run_id = ?1 AND island_id = ?2"
                        ),
                        &[sqlite_run_id(storage.run_id), island.into()],
                    )?
                    .get_typed(0)?;
                assert!(
                    rows > 0,
                    "{table} has no rows for island {island}, so the partition is uneven \
                     even though it holds {ISLANDS} distinct values"
                );
            }
        }

        storage.close()?;
        Ok(())
    }

    /// Ancestry coherence is run-scoped, so it refuses the uid reuse V15 made storable.
    ///
    /// bd-16g.5.5, second obstacle. Every island mints `AgentUid` from its own counter
    /// (bd-8jlj), so island 0's agent 1 and island 1's agent 1 are DIFFERENT organisms. V15
    /// lifted the `births` unique indexes to include `island_id` precisely so the database can
    /// hold both. The Rust-side ancestry guard is a separate layer and still reasons per run:
    /// it sees the second arrival as a duplicate identity and refuses the batch.
    ///
    /// So partitioning the schema was necessary and is not sufficient. Whoever wires the
    /// barrier has to carry `island_id` into the ancestry/coherence checks as well, or an
    /// archipelago cannot persist its births at all. Recorded as a test rather than a comment
    /// so it is discovered by running the suite rather than by reading it.
    #[test]
    fn ancestry_coherence_is_run_scoped_and_refuses_per_island_uid_reuse()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-island-ancestry-scope");
        let path_string = path.to_string_lossy().to_string();
        let mut storage =
            Storage::create_unattributed_file_with_thresholds(&path_string, 1, 1, 1, 1)?;

        let mut island_zero = sample_batch(10, 1.0);
        island_zero.births = vec![sample_birth(10, 1, BirthOrigin::Born)];
        island_zero.summary.births = 1;
        island_zero
            .events
            .push(PersistenceEvent::new(PersistenceEventKind::Births, 1));
        storage.persist_for_island(&island_zero, IslandId(0))?;

        // Island 1's own agent 1, at a free tick so admission cannot be what refuses it.
        let mut island_one = sample_batch(11, 1.0);
        island_one.births = vec![sample_birth(11, 1, BirthOrigin::Born)];
        island_one.summary.births = 1;
        island_one
            .events
            .push(PersistenceEvent::new(PersistenceEventKind::Births, 1));
        let refusal = storage
            .persist_for_island(&island_one, IslandId(1))
            .expect_err("ancestry accepted a per-island uid reuse; this test is now stale");
        assert!(
            refusal
                .to_string()
                .contains("agent uid 1 already has a persisted arrival"),
            "the refusal must be the run-scoped arrival guard, which is the layer that has to \
             become island-aware, got: {refusal}"
        );

        storage.close()?;
        Ok(())
    }

    /// Admission, not the schema, is what still blocks a real barrier (bd-16g.5.5).
    ///
    /// V15 partitioned the seven science tables, and `persist_for_island` now carries the
    /// island onto every row. This pins the obstacle ONE LAYER ABOVE that: the outbox batch
    /// ledger admits a single batch per `(run_id, tick)`, so two islands submitting the same
    /// tick as SEPARATE batches are refused at admission with a payload-digest conflict,
    /// before any island-aware code runs.
    ///
    /// THIS VINDICATES bd-16g.5.5's ORIGINAL "ONE BATCH PER BARRIER" WORDING, which I had
    /// recorded a deviation from. I argued that per-island batches submitted serially in
    /// ascending island order were equivalent, because the property at stake is that batch
    /// identity must not depend on thread scheduling. That reasoning was right about
    /// determinism and wrong about admission: the ledger is keyed by tick, so per-island
    /// batches at one tick collide by construction no matter what order they are submitted in.
    /// The barrier must fuse all islands' rows into ONE batch, exactly as the bead said.
    ///
    /// Written as a characterization of the CURRENT boundary rather than an aspiration: it
    /// goes red the moment barrier fusion lands, which forces it to be rewritten rather than
    /// left behind asserting something that is no longer true.
    #[test]
    fn same_tick_multi_island_submission_is_refused_by_the_batch_ledger()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-island-same-tick");
        let path_string = path.to_string_lossy().to_string();
        let mut storage =
            Storage::create_unattributed_file_with_thresholds(&path_string, 1, 1, 1, 1)?;

        storage.persist_for_island(&sample_batch(7, 1.0), IslandId(0))?;

        // A different island, same tick, and a payload that genuinely differs.
        let refusal = storage
            .persist_for_island(&sample_batch(7, 2.0), IslandId(1))
            .expect_err("the batch ledger accepted two islands at one tick");
        let message = refusal.to_string();
        assert!(
            message.contains("tick 7 was already admitted"),
            "the refusal must come from tick-keyed admission, which is the thing that has to \
             change for a barrier to submit N islands at one tick, got: {message}"
        );

        // CONTROL: the same island-1 payload at a free tick is admitted, so the refusal above
        // is attributable to the tick collision rather than to anything about island 1.
        storage.persist_for_island(&sample_batch(8, 2.0), IslandId(1))?;

        storage.close()?;
        Ok(())
    }

    #[test]
    fn persist_batch_writes_all_tables() -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-persist");
        let path_string = path.to_string_lossy().to_string();
        let mut storage =
            Storage::create_unattributed_file_with_thresholds(&path_string, 1, 1, 1, 1)?;

        let batch = sample_batch(42, 5.5);
        storage.persist(&batch)?;
        storage.flush()?;

        let tick_count: i64 = storage
            .connection()?
            .query_row_with_params(
                "SELECT COUNT(*) FROM tick_summaries WHERE run_id = ?1",
                &[sqlite_run_id(storage.run_id)],
            )?
            .get_typed(0)?;
        assert_eq!(tick_count, 1);

        let metric_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM metrics")?
            .get_typed(0)?;
        assert_eq!(metric_count, batch.metrics.len() as i64);

        let event_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM events")?
            .get_typed(0)?;
        assert_eq!(event_count, batch.events.len() as i64);

        let agent_count: i64 = storage
            .connection()?
            .query_row("SELECT COUNT(*) FROM agents")?
            .get_typed(0)?;
        assert_eq!(agent_count, batch.agents.len() as i64);

        let latest = storage.latest_metrics(8)?;
        assert_eq!(latest.len(), batch.metrics.len());
        assert!(latest.iter().all(|m| m.tick == 42));

        storage.close()?;
        let _ = fs::remove_file(path);
        Ok(())
    }

    #[test]
    fn finished_reader_exposes_complete_canonical_analysis_windows()
    -> Result<(), Box<dyn std::error::Error>> {
        let path = temp_db_path("storage-phenotype-window");
        let path_string = path.to_string_lossy().to_string();
        let mut storage =
            Storage::create_unattributed_file_with_thresholds(&path_string, 1, 1, 1, 1)?;

        let mut first = sample_batch(0, 5.0);
        first.births = vec![
            sample_birth(0, 1, BirthOrigin::Seeded),
            sample_birth(0, 2, BirthOrigin::Seeded),
        ];
        first.agents[0].data.velocity = Velocity::new(3.0, 4.0);
        first.agents[0].runtime.herbivore_tendency = 0.25;
        first.agents[0].runtime.trait_modifiers.smell = 1.0;
        first.agents[0].runtime.trait_modifiers.sound = 2.0;
        first.agents[0].runtime.trait_modifiers.hearing = 3.0;
        first.agents[0].runtime.trait_modifiers.eye = 4.0;
        first.agents[0].runtime.trait_modifiers.blood = 5.0;
        storage.persist(&first)?;

        let mut second = sample_batch(2, 4.0);
        second.agents[0].data.velocity = Velocity::new(0.0, 2.0);
        second.replay_events.push(ReplayEvent {
            agent_uid: Some(AgentUid(1)),
            position: Some(Position::new(1.0, 2.0)),
            counterpart: Some(AgentUid(2)),
            counterpart_position: Some(Position::new(3.0, 4.0)),
            kind: ReplayEventKind::Interaction {
                tick: Tick(2),
                ordinal: 0,
                kind: ReplayInteractionKind::Combat,
                magnitude: 1.5,
            },
        });
        second.events.extend([
            PersistenceEvent::new(
                PersistenceEventKind::Custom(INTERACTION_EVENTS_OBSERVED_KIND.into()),
                1,
            ),
            PersistenceEvent::new(
                PersistenceEventKind::Custom(INTERACTION_EVENTS_PERSISTED_KIND.into()),
                1,
            ),
        ]);
        storage.persist(&second)?;
        storage.flush()?;
        storage.close()?;

        let reader = StorageReader::open_finished(&path_string)?;
        let first_window = reader.load_agent_observations(0, 2)?;
        assert_eq!(first_window.len(), 1);
        assert_eq!(first_window[0].tick, 0);
        assert_eq!(first_window[0].agent_uid, AgentUid(1));
        assert_eq!(first_window[0].velocity_x, 3.0);
        assert_eq!(first_window[0].velocity_y, 4.0);
        assert_eq!(first_window[0].herbivore_tendency, 0.25);
        assert_eq!(first_window[0].trait_blood, 5.0);

        let all_observations = reader.load_agent_observations(0, 3)?;
        assert_eq!(
            all_observations
                .iter()
                .map(|row| (row.agent_uid, row.tick))
                .collect::<Vec<_>>(),
            vec![(AgentUid(1), 0), (AgentUid(1), 2)]
        );
        let interactions = reader.load_interactions_window(0, 3)?;
        assert_eq!(interactions.len(), 1);
        assert_eq!(interactions[0].actor, AgentUid(1));
        assert_eq!(interactions[0].target, AgentUid(2));
        assert_eq!(interactions[0].kind, "combat");
        assert_eq!(interactions[0].value, Some(1.5));
        assert_eq!(
            reader.load_interaction_capture()?,
            PersistedInteractionCapture {
                observed: 1,
                persisted: 1,
                sampled_out: 0,
                truncated: 0,
            }
        );
        assert_invalid_data_context(
            reader.load_agent_observations(2, 2),
            "agents.analysis_window",
        );
        reader.close()?;
        Ok(())
    }

